function diagonals(matrix) {
  const primary = [], secondary = [];
  const n = matrix.length;
  for (let i = 0; i < n; i++) {
    primary.push(matrix[i][i]);
    secondary.push(matrix[i][n - 1 - i]);
  }
  return { primary, secondary };
}
